/* ================= 細節收口（照參考圖 4/5）================= */
/* 標題 / 分區標題用襯線展示字（參考圖 5 的 Special day / Check-in） */
.month-title,
.section-title,
.overlap-title-text,
.memory-title,
.report-header,
.stat-name,
.timeline-header-title {
