    padding: 16px 8px;
    box-shadow: var(--ig-shadow);
}

.nuo-cal-memory .achievement-list-grid .badge-name {
    color: var(--ig-ink) !important;
}

/* 寄語：筆記本（just us 那張）：左側一排線圈 + 膠帶 */
.nuo-cal-memory .message-letter-paper {
    padding-left: 40px !important;
    border-radius: 12px 20px 20px 12px !important;
}

.nuo-cal-memory .message-letter-paper::before {
    content: '';
    position: absolute;
    left: 10px;
    top: 22px;
    bottom: 22px;
    width: 14px;
    background: repeating-radial-gradient(circle at 7px 7px, #c4c5ca 0 4px, transparent 4.5px 100%) 0 0 / 14px 22px repeat-y;
    pointer-events: none;
}

.nuo-cal-memory .message-letter-paper::after {
    content: '';
    position: absolute;
    top: -10px;
    right: 26px;
    width: 70px;
    height: 20px;
    transform: rotate(4deg);
    background: repeating-linear-gradient(-45deg, rgba(0, 0, 0, 0.05) 0 4px, transparent 4px 8px), rgba(225, 225, 230, 0.92);
    border-radius: 2px;
    pointer-events: none;
}

.nuo-cal-memory .envelope-overlay {
    background: var(--ig-paper) !important;
    color: var(--ig-ink);
}

.nuo-cal-memory .envelope-overlay div {
    color: var(--ig-ink) !important;
}

