/* 兩個統計（今日行程 / 今日待辦）改成 IG 數字欄的灰標籤 */
.nuo-cal-timeline .stat-row span {
    background: var(--ig-paper-2);
    border-radius: 999px;
    padding: 3px 10px;
    font-size: 0.72rem !important;
