    background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 24'><rect x='0' y='0' width='94' height='24' rx='8' fill='%23dcdce2'/><rect x='102' y='0' width='94' height='24' rx='8' fill='%23f0f0f3'/><text x='47' y='16.5' font-family='Helvetica,Arial,sans-serif' font-size='10' font-weight='700' fill='%236f7175' text-anchor='middle'>follow</text><text x='149' y='16.5' font-family='Helvetica,Arial,sans-serif' font-size='10' font-weight='700' fill='%236f7175' text-anchor='middle'>message</text></svg>") 0 12px / 200px 24px no-repeat;
    pointer-events: none;
}

/* 心情糯米糰 → 圓形頭像鈕 */
.nuo-cal-timeline .mood-trigger {
    background: var(--ig-paper-2);
    border-radius: 50%;
    width: 52px !important;
    height: 52px !important;
    filter: grayscale(0.7);
}

/* 彩色 emoji 一律洗成灰階（IG 貼紙表只有黑白灰） */
