.nuo-cal-timeline .bubble-location,
.nuo-cal-timeline .todo-text-col > div:not(.todo-text),
.nuo-cal-memory .caption-date,
.nuo-cal-memory .report-header {
    filter: grayscale(1);
}

/* ---- 底欄：IG 風純黑細線列 ---- */
