    gap: 5px;
}

.nuo-cal-nav-btn > svg {
    width: 25px;
    height: 25px;
    stroke-width: 1.7;
}

.nuo-cal-nav-btn span {
    font-size: 0.52rem;
    letter-spacing: 1.4px;
    text-transform: uppercase;
